-- Lets the app edit user account setup (the legacy `access` and `access_trans` tables). NOT a table-wide grant:
-- only the columns the screen can edit. Password, one-time-code secret, username and the link to a client record
-- are not in the list, so the app cannot change them. Run by an administrator; safe to repeat.

GRANT UPDATE (AccessLName, AccessFName, AccessMName, AccessSName, AccessSMSNumber, AccessLevel, AccessCurrAssign, AccessTellerNumber, AccessIsHeadCashier, AccessPassbookInitial, AccessIsDisabled, AccessCanAccessConso, AccessExpiryDate, AccessMaxLogins, AccessExpiresInDays, AccessConnTimeOut, AccessRestrictLicenseDept, AccessDepartment, AccessCanChooseDepartment, AccessRestrik, AccessRequireLoginOTP, AccessCanReverse, AccessCanPostPartialPayment, AccessCanPostWithHold, AccessCanPostOverPayment, AccessCanPostUncleared, AccessTagApproved, AccessCanOverrideNonCashPayment, AccessCanGrantRebate, AccessCanBackDateFO, AccessCanBackDateBO, AccessCanFutureDateBO, AccessCanEncodePDCFO, AccessCanEncodePDC_FO, AccessCanEncodeCOCI_FO, AccessCanViewFOCashCOCI, AccessCanAccessFrontOffice, AccessCanAccessBackOffice, AccessDisbursementLimit, AccessDisbLimit, AccessMaxWithdrawal, AccessCanAccessPOS, AccessPOSLocation, AccessPriorityObjName, AccessPOS_OperationType, AccessRestrictItemStoreTag, AccessCanViewItemCost, AccessCanEditPriceRR, AccessCanEditAverageCost, AccessCanChangePOSLocation, AccessCanRemovePunchedItemPOS, AccessCanOverrideSalesReturn, AccessCanOverrideDiscount, AccessCanUseDuplicateBarcode, AccessCanAddNewClient, AccessCanEditClient, AccessCanDeleteClient, AccessCanEditClientName, AccessCanEditClientImages, AccessCanViewClosedClients, AccessCanCloseClient, AccessCanApproveClient, AccessCanEditClientDept, AccessCanTransactClientWARNING, AccessCanTransactClosedClient, AccessIsClientIDDefaultPrompt, AccessCanEditClientSMSNumber, AccessCanEditClientEmailAddress, AccessCanEditClientSourcesOfIncome, AccessMaxClientSourcesOfIncome, AccessCanEditClientCreditLimit, AccessMaxClientCreditLimit, AccessCanApproveClientType, AccessCanAddHold, AccessCanDeleteHold, AccessCanModifyHold, AccessCanCreateLoanSetup, AccessCanEditLoanSetup, AccessCanBatchEditLoanSetups, AccessCanAddLoanApplication, AccessCanEditLoanApplication, AccessCanDeleteLoanApplication, AccessCanVerifyLoanApplication, AccessCanApproveLoanApplication, AccessCanReleaseLoan, AccessMustUseLoanWizard, AccessCanGenerateSOA, AccessCanBatchGenerateSOA, AccessCanExportPrintSOA, AccessCanCreateNewSD, AccessCanCreateNewTD, AccessCanCreateNewSC, AccessCanCreateNewIDP, AccessCanBatchProcessDeposits, AccessDepBalLimit, AccessDepBalLimitSC, AccessDepBalLimitTD, AccessCanAddCheckBook, AccessCanEditCheckBook, AccessCanDeleteCheckBook, AccessCanApproveCheckBook, AccessCanReleaseCheckBook, AccessCanModifyCheckStatusRemarks, AccessCanOverrideModifyCheckStatusRemarks, AccessCanExportReport, AccessCanGenerateFS, AccessCanGenOtherFORep, AccessCanGenRepNoRestrict, AccessCanViewActvtLogs, AccessCanBatchGenerateSMS, AccessCanApproveSMS, AccessCanSendSMS, AccessCanAccessSLView, AccessCanOpenATMGW, AccessATMTerminalID, AccessCanRunRequestServer, AccessCanTerminateUser, AccessCanDoDCM, AccessCanRegAttendanceNoFP) ON iaccsbsucmpc01.access TO 'coop_app'@'localhost';

GRANT UPDATE (CAN_FIND, CAN_NEW, CAN_EDIT, CAN_EDIT_ENTRY, CAN_DELETE, CAN_TAG_APPROVED, CAN_POST, CAN_REVERSE, CAN_CANCEL, CAN_BACKDATE, CAN_FUTUREDATE, CAN_POST_AUTO, CAN_POST_PARTIALPAY, CAN_POST_OVERPAY, CAN_POST_UNCLEAREDDEP, CAN_POST_WITH_HOLD_DEP, CAN_POST_RESULTSNEGATIVE, CAN_SEE_OTHER_USERS_TRANS, CAN_BACKDATE_CLOSEDBOOKS) ON iaccsbsucmpc01.access_trans TO 'coop_app'@'localhost';

FLUSH PRIVILEGES;
